-- Initial additive schema for the Estudos AVA.
-- IDs remain TEXT to preserve the identifiers already generated by the PWA.
-- This migration creates tables and policies; it does not import localStorage data.

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.courses (
  id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null,
  category text not null default '',
  description text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id, user_id),
  unique (id, user_id)
);

create table if not exists public.modules (
  id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null,
  title text not null,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id, user_id),
  unique (id, course_id, user_id),
  foreign key (course_id, user_id)
    references public.courses(id, user_id) on delete cascade
);

create table if not exists public.lessons (
  id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null,
  module_id text not null,
  title text not null,
  description text not null default '',
  notes text not null default '',
  status text not null default 'planned'
    check (status in ('planned', 'studying', 'practicing', 'learned', 'mastered', 'review')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id, user_id),
  unique (id, course_id, user_id),
  foreign key (course_id, user_id)
    references public.courses(id, user_id) on delete cascade,
  foreign key (module_id, course_id, user_id)
    references public.modules(id, course_id, user_id) on delete cascade
);

create table if not exists public.review_cards (
  id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text,
  lesson_id text,
  course_title text not null default '',
  front text not null,
  back text not null,
  due date,
  interval integer not null default 0 check (interval >= 0),
  repetitions integer not null default 0 check (repetitions >= 0),
  last_reviewed date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id, user_id),
  foreign key (course_id, user_id)
    references public.courses(id, user_id) on delete cascade,
  foreign key (lesson_id, course_id, user_id)
    references public.lessons(id, course_id, user_id) on delete cascade
);

create table if not exists public.resources (
  id text not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text,
  title text not null,
  type text not null default 'Outro',
  url text not null default '',
  description text not null default '',
  course_title text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id, user_id),
  foreign key (course_id, user_id)
    references public.courses(id, user_id) on delete cascade
);

create index if not exists courses_user_updated_idx
  on public.courses (user_id, updated_at desc);
create index if not exists modules_course_position_idx
  on public.modules (course_id, position);
create index if not exists lessons_course_module_idx
  on public.lessons (course_id, module_id);
create index if not exists review_cards_user_due_idx
  on public.review_cards (user_id, due);
create index if not exists resources_user_created_idx
  on public.resources (user_id, created_at desc);

alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.modules enable row level security;
alter table public.lessons enable row level security;
alter table public.review_cards enable row level security;
alter table public.resources enable row level security;

create policy "profiles_select_own"
  on public.profiles for select to authenticated
  using (id = (select auth.uid()));
create policy "profiles_update_own"
  on public.profiles for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

create policy "courses_owner_all"
  on public.courses for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "modules_owner_all"
  on public.modules for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "lessons_owner_all"
  on public.lessons for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "review_cards_owner_all"
  on public.review_cards for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "resources_owner_all"
  on public.resources for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();
create trigger courses_set_updated_at
  before update on public.courses
  for each row execute function public.set_updated_at();
create trigger modules_set_updated_at
  before update on public.modules
  for each row execute function public.set_updated_at();
create trigger lessons_set_updated_at
  before update on public.lessons
  for each row execute function public.set_updated_at();
create trigger review_cards_set_updated_at
  before update on public.review_cards
  for each row execute function public.set_updated_at();
create trigger resources_set_updated_at
  before update on public.resources
  for each row execute function public.set_updated_at();

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'name', new.raw_user_meta_data ->> 'full_name', ''))
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();
